SELECT s.original_writer_xid::pg_catalog.text AS original_writer_xid, s.operation_ordinal::pg_catalog.text AS operation_ordinal, s.stage_name AS stage_name, s.stage_ordinal::pg_catalog.text AS stage_ordinal, s.effect_generation::pg_catalog.text AS effect_generation, pg_catalog.encode(s.body_bytes, 'hex') AS body_bytes_hex FROM truss.row_home_journal_stage s WHERE s.original_writer_xid = $1::pg_catalog.xid8 AND s.operation_ordinal = $2::bigint